import { DotPattern } from "../magicui/DotPattern";

export default function Demo() {
  return (
    <div className="relative flex min-h-[420px] w-full items-center justify-center overflow-hidden bg-background p-8">
      <DotPattern
        glow
        width={24}
        height={24}
        cr={1.4}
